		const centerY = (jointFrom.y + jointTo.y) / 2;
		const boneLength = Math.sqrt((jointTo.x - jointFrom.x) ** 2 + (jointTo.y - jointFrom.y) ** 2);
		const boneAngle = Math.atan2(jointTo.y - jointFrom.y, jointTo.x - jointFrom.x) * 180 / Math.PI;
